fn bowling_score(rolls: List[Int]) -> Result[Int, String] {
  if any(|r| r < 0 || r > 10) {
    return Err("invalid roll")
  }
  var score = 0
  var i = 0
  for _ in range(0, 10) {
    if rolls[i] == 10 {
      score = score + 10 + rolls[i + 1] + rolls[i + 2]
      i = i + 1
    } else if rolls[i] + rolls[i + 1] > 10 {
      return Err("too many pins in frame " + to_string(i / 2 + 1))
    } else {
      score = score + rolls[i] + rolls[i + 1]
    }
    i = i + 2
  }
  if i < len(rolls) {
    return Err("too many rolls")
  }
  return Ok(score)
}

