type Person {
  name: String,
  age: Int,
}

fn age_histogram(people: List[Person], width: Int) -> Result[List[(String, Int)], String] {
  if width < 1 {
    return Err("bad width".to_string());
  }
  let mut buckets = Map::new();
  for p in people {
    if p.age < 0 {
      return Err(format!("negative age: {}", p.name));
    }
    let bucket = p.age / width * width;
    let count = buckets.get_or_insert(bucket, 0);
    buckets.set(bucket, count + 1);
  }
  let mut result = Vec::new();
  let mut min_bucket = i32::MAX;
  let mut max_bucket = i32::MIN;
  for (bucket, count) in buckets {
    if bucket < min_bucket {
      min_bucket = bucket;
    }
    if bucket > max_bucket {
      max_bucket = bucket;
    }
  }
  for bucket in min_bucket..=max_bucket {
    let label = format!("{}-{}", bucket, bucket + width - 1);
    result.push((label, buckets.get_or_insert(bucket, 0)));
  }
  Ok(result)
}

