type Shift {
  worker: String,
  start_hour: Int,
  end_hour: Int,
}

fn coverage_gaps(shifts: List[Shift], required: Int) -> List[Int] {
  var coverage = [0; 24]
  for shift in shifts {
    for h in range(shift.start_hour, shift.end_hour) {
      coverage[h] = coverage[h] + 1
    }
  }
  return filter(enumerate(coverage), |(h, count)| count < required).map(|(h, _)| h)
}

