type Line {
  sku: String,
  qty: Int,
  unit_cents: Int,
}

fn invoice_total(lines: List[Line], coupon: String) -> Result[Int, String] {
  let mut subtotal = 0;
  for line in lines {
    if line.qty < 1 {
      return Err("bad quantity: " + line.sku);
    }
    let amount = line.qty * line.unit_cents;
    if line.qty >= 10 {
      amount = amount - (amount / 10);
    }
    subtotal = subtotal + amount;
  }
  let mut amount = subtotal;
  if coupon == "SAVE500" {
    amount = amount - 500;
    if amount < 0 {
      amount = 0;
    }
  } else if coupon == "PCT10" {
    amount = amount - (subtotal / 10);
  } else if coupon == "BIG20" {
    if subtotal >= 10000 {
      amount = amount - (subtotal / 5);
    } else {
      return Err("coupon not applicable: BIG20");
    }
  } else if coupon != "" {
    return Err("unknown coupon: " + coupon);
  }
  let tax = (amount * 8 + 50) / 100;
  amount = amount + tax;
  return Ok(amount);
}

