fn pig_latin(s: String) -> String {
  return s
    |> split(" ")
    |> map(translate_word)
    |> join(" ")
}

fn translate_word(word: String) -> String {
  let vowels = "aeiou";
  let mut chars = word.chars();
  let first_char = chars.next().unwrap();
  let mut has_vowel = false;

  if first_char == 'q' {
    if let Some('u') = chars.next() {
      return word + "way";
    }
  }

  for (i, c) in chars.enumerate() {
    if vowels.contains(c) {
      has_vowel = true;
      return word[i..] + &word[0..i] + "ay";
    }
  }

  if !has_vowel {
    return word + "ay";
  }

  return word;
}

