}

fn settle_debts(expenses: List[Expense], people: List[String]) -> List[(String, String, Int)] {
  let total = expenses |> map(|e| e.amount_cents) |> sum
  let per_person = total / len(people)
  let remainder = total % len(people)
  let mut balances = map_from(people |> map(|p| (p, per_person)))
  for p in people {
    balances = map_set(balances, p, balances |> map_get(p) |> unwrap_or(0) + expenses |> filter(|e| e.payer == p) |> map(|e| e.amount_cents) |> sum)
  }
  let mut payments = []
  while balances |> map_values(|b| abs(b)) |> sum > 0 {
    let debtor = balances |> map(|(p, b)| (p, b)) |> filter(|(_, b)| b < 0) |> sort_by(|(_, b)| b) |> first |> unwrap_or(("","0"))
    let creditor = balances |> map(|(p, b)| (p, b)) |> filter(|(_, b)| b > 0) |> sort_by(|(_, b)| -b) |> first |> unwrap_or(("","0"))
    let amount = min(abs(balances |> map_get(debtor.0) |> unwrap_or(0)), balances |> map_get(creditor.0) |> unwrap_or(0))
    payments = append(payments, (debtor.0, creditor.0, amount))
    balances = map_set(balances, debtor.0, balances |> map_get(debtor.0) |> unwrap_or(0) + amount)
    balances = map_set(balances, creditor.0, balances |> map_get(creditor.0) |> unwrap_or(0) - amount)
  }
  return payments
}

