fn spiral_order(m: List[List[Int]]) -> List[Int] {
  let rows = len(m);
  let cols = rows > 0 ? len(m[0]) : 0;
  let mut result = [];
  let mut top = 0;
  let mut bottom = rows - 1;
  let mut left = 0;
  let mut right = cols - 1;

  while top <= bottom && left <= right {
    for i in left..=right {
      append(result, m[top][i]);
    }
    top = top + 1;

    for i in top..=bottom {
      append(result, m[i][right]);
    }
    right = right - 1;

    if top <= bottom {
      for i in (left..=right).rev() {
        append(result, m[bottom][i]);
      }
      bottom = bottom - 1;
    }

    if left <= right {
      for i in (top..=bottom).rev() {
        append(result, m[i][left]);
      }
      left = left + 1;
    }
  }

  return result;
}

