fn top_product_per_region(sales: List[Sale>) -> List[(String, String, Int)] {
  let mut region_revenue = Map[String, Map[String, Int]]()
  for sale in sales {
    let region_sales = map_get(region_revenue, sale.region) |> unwrap_or(map_new())
    let new_revenue = region_sales[sale.product] + sale.units * sale.price_cents
    map_set(region_sales, sale.product, new_revenue)
    map_set(region_revenue, sale.region, region_sales)
  }
