from typing import Callable, Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Open(TypedDict):
    kind: Literal["Open"]
    name: str

class Deposit(TypedDict):
    kind: Literal["Deposit"]
    name: str
    amount: int

class Withdraw(TypedDict):
    kind: Literal["Withdraw"]
    name: str
    amount: int

class Transfer(TypedDict):
    kind: Literal["Transfer"]
    src: str
    dst: str
    amount: int

BankOp = Open | Deposit | Withdraw | Transfer

def bank_ledger(ops: list[BankOp]) -> Ok[list[tuple[str, int]]] | Err:
    accounts: dict[str, int] = {}
    for i, op in enumerate(ops, start=1):
        if op["kind"] == "Open":
            if op["name"] in accounts:
                return Err({"ok": False, "error": f"step {i}: duplicate account {op['name']}"})
            accounts[op["name"]] = 0
        elif op["kind"] == "Deposit":
            if op["name"] not in accounts:
                return Err({"ok": False, "error": f"step {i}: unknown account {op['name']}"})
            if op["amount"] <= 0:
                return Err({"ok": False, "error": f"step {i}: invalid amount"})
            accounts[op["name"]] += op["amount"]
        elif op["kind"] == "Withdraw":
            if op["name"] not in accounts:
                return Err({"ok": False, "error": f"step {i}: unknown account {op['name']}"})
            if op["amount"] <= 0:
                return Err({"ok": False, "error": f"step {i}: invalid amount"})
            if accounts[op["name"]] < op["amount"]:
                return Err({"ok": False, "error": f"step {i}: insufficient funds"})
            accounts[op["name"]] -= op["amount"]
        elif op["kind"] == "Transfer":
            if op["src"] not in accounts:
                return Err({"ok": False, "error": f"step {i}: unknown account {op['src']}"})
            if op["dst"] not in accounts:
                return Err({"ok": False, "error": f"step {i}: unknown account {op['dst']}"})
            if op["src"] == op["dst"]:
                return Err({"ok": False, "error": f"step {i}: same account"})
            if op["amount"] <= 0:
                return Err({"ok": False, "error": f"step {i}: invalid amount"})
            if accounts[op["src"]] < op["amount"]:
                return Err({"ok": False, "error": f"step {i}: insufficient funds"})
            accounts[op["src"]] -= op["amount"]
            accounts[op["dst"]] += op["amount"]
    return Ok({"ok": True, "value": list(accounts.items())})

