    result, pos = parse_factor(s, pos)
    while pos < len(s) and s[pos] in "*/":
        op = s[pos]
        pos += 1
        next_result, pos = parse_factor(s, pos)
        if op == "*":
            result *= next_result
        else:
            if next_result == 0:
                return 0, "division by zero"
            result //= next_result
    return result, pos

def parse_factor(s: str, pos: int) -> tuple[int, str]:
    if pos < len(s) and s[pos] == "(":
        pos += 1
        result, pos = parse_expr(s, pos)
        if pos < len(s) and s[pos] == ")":
            pos += 1
            return result, pos
        else:
            return 0, "expected )"
