    error: str

class Line(TypedDict):
    sku: str
    qty: int
    unit_cents: int

def invoice_total(lines: list[Line], coupon: str) -> Ok[int] | Err:
    if not lines:
        return Ok(value=0)

    for line in lines:
        if line["qty"] < 1:
            return Err(error=f"bad quantity: {line['sku']}")

    subtotal = 0
    for line in lines:
        amount = line["qty"] * line["unit_cents"]
        if line["qty"] >= 10:
            amount -= amount // 10
        subtotal += amount

    if coupon == "SAVE500":
        subtotal = max(subtotal - 500, 0)
    elif coupon == "PCT10":
        subtotal -= subtotal // 10
    elif coupon == "BIG20":
        if subtotal >= 10000:
            subtotal -= subtotal // 5
        else:
            return Err(error="coupon not applicable: BIG20")
    elif coupon:
        return Err(error=f"unknown coupon: {coupon}")

    tax = (subtotal * 8 + 50) // 100
    total = subtotal + tax
    return Ok(value=total)

