        elif s[i] in units:
            if i == 0 or not s[i-1].isdigit():
                return Err(ok=False, error=f"missing number before {s[i]}")
            total_seconds += number * units[s[i]]
            i += 1
        else:
            return Err(ok=False, error=f"unknown unit: {s[i]}")

    if i < len(s) and s[i:].isdigit():
        return Err(ok=False, error="missing unit")

    return Ok(ok=True, value=total_seconds)

