    error: str

def parse_money(s: str) -> Ok[int] | Err:
    if s.startswith('-'):
        s = s[1:]
        negate = True
    else:
        negate = False

    if not s.startswith('$'):
        return Err(ok=False, error="missing $")

    s = s[1:]

    if '.' in s:
        dollars, cents = s.split('.', 1)
        if len(cents) != 2:
            return Err(ok=False, error="bad cents")
    else:
        dollars = s
        cents = '00'

    if not dollars:
        return Err(ok=False, error="bad dollars")

    if dollars[0] == '0' and len(dollars) > 1:
        return Err(ok=False, error="bad dollars")

    if not dollars.isdigit():
        return Err(ok=False, error="bad dollars")

    if not cents.isdigit():
        return Err(ok=False, error="bad cents")

    value = int(dollars) * 100 + int(cents)
    if negate:
        value = -value

    return Ok(ok=True, value=value)

