def roman_to_int(s: str) -> Ok[int] | Err:
    if not s:
        return Err(ok=False, error="empty")

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    if s[0] not in roman_map:
        return Err(ok=False, error=f"invalid character: {s[0]}")

    prev_value = 0
    total = 0

    for char in reversed(s):
        value = roman_map[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value

    if not (1 <= total <= 3999):
        return Err(ok=False, error="not canonical")

    return Ok(ok=True, value=total)

