export function align_columns(rows: string[][]): string[] {
    const columnWidths = new Array<number>(rows.reduce((max, row) => Math.max(max, row.length), 0)).fill(0);

    rows.forEach(row => {
        row.forEach((cell, index) => {
            columnWidths[index] = Math.max(columnWidths[index], cell.length);
        });
    });

    return rows.map(row => {
        return row.map(cell => cell.padEnd(columnWidths[row.indexOf(cell)], ' ')).join(' | ').trimEnd();
    });
}

