type Person = { name: string; age: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function age_histogram(people: Person[], width: number): Result<([string, number])[]> {
    if (width < 1) return { ok: false, error: "bad width" };
    const ageCounts: { [key: string]: number } = {};
    for (const person of people) {
        if (person.age < 0) return { ok: false, error: `negative age: ${person.name}` };
        const bucket = Math.floor(person.age / width) * width;
        const label = `${bucket}-${bucket + width - 1}`;
        ageCounts[label] = (ageCounts[label] || 0) + 1;
    }
    const result: [string, number][] = [];
    let minBucket = Infinity;
    let maxBucket = -Infinity;
    for (const bucket in ageCounts) {
        const [start, end] = bucket.split('-').map(Number);
        minBucket = Math.min(minBucket, start);
        maxBucket = Math.max(maxBucket, end);
    }
    for (let bucket = minBucket; bucket <= maxBucket; bucket += width) {
        const label = `${bucket}-${bucket + width - 1}`;
        result.push([label, ageCounts[label] || 0]);
    }
    return { ok: true, value: result };
}

