type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bowling_score(rolls: number[]): Result<number> {
    if (rolls.some(r => r < 0 || r > 10)) return { ok: false, error: "invalid roll" };

    let score = 0;
    let rollIndex = 0;

    for (let frame = 0; frame < 10; frame++) {
        if (rollIndex >= rolls.length) return { ok: false, error: "incomplete game" };

        if (rolls[rollIndex] === 10) {
            // Strike
            score += 10 + rolls[rollIndex + 1] + rolls[rollIndex + 2];
            rollIndex++;
        } else {
            // Not a strike
            if (rollIndex + 1 >= rolls.length) return { ok: false, error: "incomplete game" };
            if (rolls[rollIndex] + rolls[rollIndex + 1] > 10) return { ok: false, error: `too many pins in frame ${frame + 1}` };
            score += rolls[rollIndex] + rolls[rollIndex + 1];
            rollIndex += 2;
        }
    }

    if (rollIndex < rolls.length) return { ok: false, error: "too many rolls" };

    return { ok: true, value: score };
}

