type Job = { name: string; deps: string[] };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function build_order(jobs: Job[]): Result<string[]> {
  const jobMap = new Map<string, Job>();
  const dependencyCount = new Map<string, number>();
  const order: string[] = [];

  // Validate and build job map and dependency count
  for (const job of jobs) {
    if (jobMap.has(job.name)) {
      return { ok: false, error: `duplicate job: ${job.name}` };
    }
    jobMap.set(job.name, job);
    dependencyCount.set(job.name, 0);
  }

  for (const job of jobs) {
    for (const dep of job.deps) {
      if (!jobMap.has(dep)) {
        return { ok: false, error: `unknown dependency: ${dep}` };
      }
      dependencyCount.set(dep, dependencyCount.get(dep)! + 1);
    }
  }

  // Topological sort
  while (order.length < jobs.length) {
    let placed = false;
    for (const job of jobs) {
      if (!order.includes(job.name) && dependencyCount.get(job.name) === 0) {
        order.push(job.name);
        placed = true;
        for (const dep of job.deps) {
          dependencyCount.set(dep, dependencyCount.get(dep)! - 1);
        }
      }
    }
    if (!placed) {
      return { ok: false, error: "cycle detected" };
    }
  }

  return { ok: true, value: order };
}

