type Shift = { worker: string; start_hour: number; end_hour: number };

export function coverage_gaps(shifts: Shift[], required: number): number[] {
    const coverage = new Array(24).fill(0);

    for (const shift of shifts) {
        for (let hour = shift.start_hour; hour < shift.end_hour; hour++) {
            coverage[hour]++;
        }
    }

    return coverage
        .map((count, hour) => (count < required ? hour : null))
        .filter((hour): hour is number => hour !== null)
        .sort((a, b) => a - b);
}

