function count_islands(grid: string[]): [number, number] {
    if (grid.length === 0 || grid[0].length === 0) return [0, 0];

    const rows = grid.length;
    const cols = grid[0].length;
    let islandCount = 0;
    let maxIslandSize = 0;

    const visited = new Array(rows).fill(null).map(() => new Array(cols).fill(false));

    function dfs(r: number, c: number): number {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] === '.' || visited[r][c]) return 0;
        visited[r][c] = true;
        return 1 + dfs(r - 1, c) + dfs(r + 1, c) + dfs(r, c - 1) + dfs(r, c + 1);
    }

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === '#' && !visited[r][c]) {
                const islandSize = dfs(r, c);
                islandCount++;
                maxIslandSize = Math.max(maxIslandSize, islandSize);
            }
        }
    }

    return [islandCount, maxIslandSize];
}

