type Key = { kind: "Digit"; d: number } | { kind: "Enter" } | { kind: "Clear" };

export function door_lock(code: string, events: Key[]): string {
    let buffer: string[] = [];
    let failureCount = 0;
    let state: "locked" | "open" | "blocked" = "locked";

    for (const event of events) {
        if (state === "locked") {
            if (event.kind === "Digit" && buffer.length < code.length) {
                buffer.push(event.d.toString());
            } else if (event.kind === "Clear") {
                buffer = [];
            } else if (event.kind === "Enter") {
                if (buffer.join('') === code) {
                    buffer = [];
                    failureCount = 0;
                    state = "open";
                } else {
                    failureCount++;
                    if (failureCount === 3) {
                        state = "blocked";
                    }
                }
            }
        } else if (state === "open" && event.kind === "Enter") {
            state = "locked";
        }
    }

    return state;
}

