function bank_ledger(ops: BankOp[]): Result<([string, number])[]> {
  const accounts: { [name: string]: number } = {};

  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    const step = i + 1;

    switch (op.kind) {
      case "Open":
        if (accounts[op.name] !== undefined) {
          return { ok: false, error: `step ${step}: duplicate account ${op.name}` };
        }
        accounts[op.name] = 0;
        break;
      case "Deposit":
        if (accounts[op.name] === undefined) {
          return { ok: false, error: `step ${step}: unknown account ${op.name}` };
        }
        if (op.amount <= 0) {
          return { ok: false, error: `step ${step}: invalid amount` };
        }
        accounts[op.name] += op.amount;
        break;
      case "Withdraw":
        if (accounts[op.name] === undefined) {
          return { ok: false, error: `step ${step}: unknown account ${op.name}` };
        }
        if (op.amount <= 0) {
          return { ok: false, error: `step ${step}: invalid amount` };
        }
        if (accounts[op.name] < op.amount) {
          return { ok: false, error: `step ${step}: insufficient funds` };
        }
        accounts[op.name] -= op.amount;
        break;
      case "Transfer":
        if (op.src === op.dst) {
          return { ok: false, error: `step ${step}: same account` };
        }
        if (accounts[op.src] === undefined) {
          return { ok: false, error: `step ${step}: unknown account ${op.src}` };
        }
        if (accounts[op.dst] === undefined) {
          return { ok: false, error: `step ${step}: unknown account ${op.dst}` };
        }
        if (op.amount <= 0) {
          return { ok: false, error: `step ${step}: invalid amount` };
        }
        if (accounts[op.src] < op.amount) {
          return { ok: false, error: `step ${step}: insufficient funds` };
        }
        accounts[op.src] -= op.amount;
        accounts[op.dst] += op.amount;
        break;
    }
  }

  return { ok: true, value: Object.entries(accounts) };
}

