export function elevator_scan(start: number, requests: number[], direction: string): number[] {
    const uniqueRequests = Array.from(new Set(requests));
    const sortedRequests = uniqueRequests.sort((a, b) => a - b);
    const result: number[] = [];

    if (direction === "up") {
        result.push(start);
        for (const floor of sortedRequests) {
            if (floor > start) result.push(floor);
        }
        for (let i = sortedRequests.length - 1; i >= 0; i--) {
            const floor = sortedRequests[i];
            if (floor < start) result.push(floor);
        }
    } else if (direction === "down") {
        result.push(start);
        for (let i = sortedRequests.length - 1; i >= 0; i--) {
            const floor = sortedRequests[i];
            if (floor < start) result.push(floor);
        }
        for (const floor of sortedRequests) {
            if (floor > start) result.push(floor);
        }
    }

    return result;
}

