type Meeting = { start: number; end: number };

export function free_slots(meetings: Meeting[], day_start: number, day_end: number): ([number, number])[] {
    if (day_end <= day_start) return [];

    const sortedMeetings = meetings.sort((a, b) => a.start - b.start);
    const freeSlots: [number, number][] = [];

    let currentStart = day_start;

    for (const meeting of sortedMeetings) {
        if (meeting.start > currentStart) {
            freeSlots.push([currentStart, meeting.start]);
        }
        currentStart = Math.max(currentStart, meeting.end);
    }

    if (currentStart < day_end) {
        freeSlots.push([currentStart, day_end]);
    }

    return freeSlots;
}

