export function heading_numbers(lines: string[]): string[] {
    const counters: { [key: number]: number } = { 1: 0, 2: 0, 3: 0 };
    const result: string[] = [];

    for (const line of lines) {
        const match = line.match(/^(\#{1,3}) (.+)$/);
        if (match) {
            const level = match[1].length;
            const title = match[2];
            counters[level]++;
            for (let i = level + 1; i <= 3; i++) {
                counters[i] = 0;
            }
            result.push(`${counters[1]}.${counters[2]}.${counters[3]} ${title}`);
        }
    }

    return result;
}

