type Line = { sku: string; qty: number; unit_cents: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function invoice_total(lines: Line[], coupon: string): Result<number> {
    if (lines.some(line => line.qty < 1)) {
        return { ok: false, error: `bad quantity: ${lines.find(line => line.qty < 1)!.sku}` };
    }

    let subtotal = 0;
    for (const line of lines) {
        let amount = line.qty * line.unit_cents;
        if (line.qty >= 10) {
            amount -= Math.floor(amount / 10);
        }
        subtotal += amount;
    }

    let discount = 0;
    switch (coupon) {
        case "SAVE500": discount = Math.max(0, subtotal - 500); break;
        case "PCT10": discount = Math.floor(subtotal / 10); break;
        case "BIG20":
            if (subtotal >= 10000) {
                discount = Math.floor(subtotal / 5);
            } else {
                return { ok: false, error: "coupon not applicable: BIG20" };
            }
            break;
        default: return { ok: false, error: `unknown coupon: ${coupon}` };
    }

    let amount = subtotal - discount;
    let tax = Math.floor((amount * 8 + 50) / 100);
    return { ok: true, value: amount + tax };
}

