type Request = { endpoint: string; ms: number; status: number };

function latency_report(entries: Request[]): [string, number, number, number][] {
    const grouped = entries.reduce((acc, entry) => {
        if (!acc[entry.endpoint]) {
            acc[entry.endpoint] = { count: 0, msValues: [], errors: 0 };
        }
        acc[entry.endpoint].count++;
        acc[entry.endpoint].msValues.push(entry.ms);
        if (entry.status >= 500) {
            acc[entry.endpoint].errors++;
        }
        return acc;
    }, {} as { [key: string]: { count: number; msValues: number[]; errors: number } });

    return Object.entries(grouped).map(([endpoint, data]) => {
        const sortedMsValues = data.msValues.sort((a, b) => a - b);
        const count = data.count;
        const p90Index = Math.floor((9 * count + 9) / 10) - 1;
        const p90 = sortedMsValues[p90Index];
        const errors = data.errors;
        return [endpoint, count, p90, errors];
    });
}

