function inventory_ledger(stock: Stock[], txns: Txn[]): Result<Stock[]> {
    const ledger = new Map(stock.map(s => [s.sku, s.qty]));
    for (let i = 0; i < txns.length; i++) {
        const { sku, delta } = txns[i];
        if (!ledger.has(sku)) return { ok: false, error: `txn ${i + 1}: unknown sku ${sku}` };
        const newQty = ledger.get(sku)! + delta;
        if (newQty < 0) return { ok: false, error: `txn ${i + 1}: ${sku} would go negative` };
        ledger.set(sku, newQty);
    }
    const result: Stock[] = [];
    for (const [sku, qty] of ledger) {
        if (qty > 0) result.push({ sku, qty });
    }
    result.sort((a, b) => a.sku.localeCompare(b.sku));
    return { ok: true, value: result };
}

