function lis_length(xs: number[]): [number, number] {
    if (xs.length === 0) return [0, 0];

    const lengths = new Array(xs.length).fill(1);
    const counts = new Array(xs.length).fill(1);

    for (let i = 1; i < xs.length; i++) {
        for (let j = 0; j < i; j++) {
            if (xs[i] > xs[j]) {
                if (lengths[j] + 1 > lengths[i]) {
                    lengths[i] = lengths[j] + 1;
                    counts[i] = counts[j];
                } else if (lengths[j] + 1 === lengths[i]) {
                    counts[i] += counts[j];
                }
            }
        }
    }

    const maxLen = Math.max(...lengths);
    const maxCount = lengths.filter((len, idx) => len === maxLen).reduce((acc, _, idx) => acc + counts[idx], 0);

    return [maxLen, maxCount];
}

