function flatten_nested(s: string): Result<[number[], number]> {
    s = s.replace(/\s/g, '');
    const result: number[] = [];
    let depth = 0, maxDepth = 0;

    function parseElement(index: number): number {
        if (s[index] === '[') {
            depth++;
            maxDepth = Math.max(maxDepth, depth);
            const start = index + 1;
            let end = start;
            while (s[end] !== ']') {
                end = parseElement(end);
            }
            depth--;
            const sublist = JSON.parse(s.slice(start, end));
            result.push(...sublist);
            return end + 1;
        } else if (s[index] === '-') {
            const num = parseInt(s.slice(index), 10);
            result.push(num);
            return index + num.toString().length;
        } else {
            const num = parseInt(s.slice(index), 10);
            result.push(num);
            return index + num.toString().length;
        }
    }

    try {
        parseElement(0);
        return { ok: true, value: [result, maxDepth] };
    } catch (e) {
        return { ok: false, error: `invalid at ${e.message}` };
    }
}

