export function max_subarray(xs: number[]): [number, number, number] | null {
    if (xs.length === 0) return null;

    let maxSum = -Infinity;
    let start = 0;
    let end = 0;
    let tempStart = 0;
    let tempSum = 0;

    for (let i = 0; i < xs.length; i++) {
        tempSum += xs[i];
        if (tempSum > maxSum) {
            maxSum = tempSum;
            start = tempStart;
            end = i;
        }
        if (tempSum < 0) {
            tempSum = 0;
            tempStart = i + 1;
        }
    }

    return [maxSum, start, end];
}

