type Contact = { name: string; email: string; phone: string };

function merge_contacts(contacts: Contact[]): Contact[] {
    if (contacts.length === 0) return [];

    const contactMap = new Map<string, Contact>();
    const linkedContacts = new Map<string, Set<string>>();

    contacts.forEach(contact => {
        const email = contact.email.trim();
        const phone = contact.phone.replace(/\D/g, '');

        if (email) {
            contactMap.set(email, contact);
            linkedContacts.set(email, new Set());
        }
        if (phone) {
            contactMap.set(phone, contact);
            linkedContacts.set(phone, new Set());
        }
    });

    contacts.forEach(contact => {
        const email = contact.email.trim();
        const phone = contact.phone.replace(/\D/g, '');

        if (email) {
            linkedContacts.get(email)?.forEach(link => {
                linkedContacts.get(link)?.add(email);
            });
        }
        if (phone) {
            linkedContacts.get(phone)?.forEach(link => {
                linkedContacts.get(link)?.add(phone);
            });
        }
    });

    const visited = new Set<string>();
    const result: Contact[] = [];

    const dfs = (email: string) => {
        if (visited.has(email)) return;
        visited.add(email);

        const contact = contactMap.get(email)!;
        result.push(contact);

        linkedContacts.get(email)?.forEach(link => {
            dfs(link);
        });
    };

    contacts.forEach(contact => {
        const email = contact.email.trim();
        if (!visited.has(email)) {
            dfs(email);
        }
    });

    return result;
}

