function min_coins(coins: number[], amount: number): [number, number[]] | null {
    if (amount < 0) return null;
    const dp: [number, number[]][] = Array(amount + 1).fill([Infinity, []]);
    dp[0] = [0, []];

    for (let i = 1; i <= amount; i++) {
        for (const coin of coins) {
            if (i >= coin) {
                const [count, used] = dp[i - coin];
                if (count + 1 < dp[i][0] || (count + 1 === dp[i][0] && used.length > 0 && used[used.length - 1] < coin)) {
                    dp[i] = [count + 1, [...used, coin].sort((a, b) => b - a)];
                }
            }
        }
    }

    return dp[amount][0] === Infinity ? null : dp[amount];
}

