function next_permutation(xs: number[]): number[] {
    let i = xs.length - 2;
    while (i >= 0 && xs[i] >= xs[i + 1]) i--;
    if (i < 0) return xs.sort((a, b) => a - b);
    let j = xs.length - 1;
    while (xs[j] <= xs[i]) j--;
    [xs[i], xs[j]] = [xs[j], xs[i]];
    let start = i + 1, end = xs.length - 1;
    while (start < end) [xs[start++], xs[end--]] = [xs[end], xs[start]];
    return xs;
}

