type Park = { kind: "Arrive"; plate: string; minute: number } | { kind: "Leave"; plate: string; minute: number };

function parking_fees(events: Park[]): ([string, number])[] {
    const parked: { [plate: string]: number } = {};
    const fees: { [plate: string]: number } = {};

    for (const event of events) {
        if (event.kind === "Arrive") {
            if (!parked[event.plate]) {
                parked[event.plate] = event.minute;
            }
        } else if (event.kind === "Leave") {
            if (parked[event.plate]) {
                const duration = event.minute - parked[event.plate];
                if (duration > 30) {
                    const hours = Math.ceil((duration - 30) / 60);
                    fees[event.plate] = (fees[event.plate] || 0) + Math.min(hours * 200, 1000);
                }
                delete parked[event.plate];
            }
        }
    }

    return Object.entries(fees).sort((a, b) => a[0].localeCompare(b[0]));
}

