            if (j === s.length) {
                return { ok: false, error: "unterminated quote" };
            }
            result.push(s.slice(i, j).replace(/\\\\"/g, '"'));
            i = j + 1;
        } else {
            let j = i;
            while (j < s.length && s[j] !== ',') {
                j++;
            }
            result.push(s.slice(i, j));
            i = j + 1;
        }
    }
    return { ok: true, value: result };
}

