type Match = { home: string; away: string; home_goals: number; away_goals: number };

function league_table(matches: Match[]): ([string, number, number, number])[] {
    const table: { [team: string]: { points: number; goals_for: number; goals_against: number } } = {};

    for (const match of matches) {
        const { home, away, home_goals, away_goals } = match;
        const home_team = home;
        const away_team = away;

        if (!table[home_team]) {
            table[home_team] = { points: 0, goals_for: 0, goals_against: 0 };
        }
        if (!table[away_team]) {
            table[away_team] = { points: 0, goals_for: 0, goals_against: 0 };
        }

        table[home_team].goals_for += home_goals;
        table[away_team].goals_for += away_goals;
        table[home_team].goals_against += away_goals;
        table[away_team].goals_against += home_goals;

        if (home_goals > away_goals) {
            table[home_team].points += 3;
        } else if (home_goals === away_goals) {
            table[home_team].points += 1;
            table[away_team].points += 1;
        }
    }

    return Object.entries(table).map(([team, { points, goals_for, goals_against }]) => [
        team,
        points,
        goals_for - goals_against,
        goals_for,
    ]).sort((a, b) => {
        if (b[1] !== a[1]) return b[1] - a[1]; // Points
        if (b[2] !== a[2]) return b[2] - a[2]; // Goal difference
        if (b[3] !== a[3]) return b[3] - a[3]; // Goals for
        return a[0].localeCompare(b[0]); // Team name
    });
}

