function parse_ipv4(s: string): Result<number> {
    const parts = s.split('.');
    if (parts.length !== 4) return { ok: false, error: 'expected 4 parts' };

    let value = 0;
    for (let i = 0; i < 4; i++) {
        const part = parts[i];
        if (!/^\d{1,3}$/.test(part)) return { ok: false, error: `bad part: ${part}` };
        const num = parseInt(part, 10);
        if (num < 0 || num > 255) return { ok: false, error: `bad part: ${part}` };
        value = value * 256 + num;
    }

    return { ok: true, value };
}

