type Employee = { name: string; dept: string; hours: number; rate_cents: number };

export function payroll_by_dept(emps: Employee[]): ([string, number])[] {
  const deptPay: { [dept: string]: number } = {};

  emps.forEach(emp => {
    const basePay = Math.min(emp.hours, 40) * emp.rate_cents;
    const overtimePay = Math.max(emp.hours - 40, 0) * emp.rate_cents * 3 / 2;
    const totalPay = basePay + overtimePay;
    if (deptPay[emp.dept]) {
      deptPay[emp.dept] += totalPay;
    } else {
      deptPay[emp.dept] = totalPay;
    }
  });

  return Object.entries(deptPay)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

