function pig_latin(s: string): string {
    return s.split(' ').map(word => translateWord(word)).join(' ');
}

function translateWord(word: string): string {
    const vowels = 'aeiou';
    let firstVowelIndex = word.length;

    // Find the index of the first vowel
    for (let i = 0; i < word.length; i++) {
        if (vowels.includes(word[i]) && !(word[i] === 'u' && word[i - 1] === 'q')) {
            firstVowelIndex = i;
            break;
        }
    }

    // If no vowel is found, treat it as if it ends with 'a'
    if (firstVowelIndex === word.length) {
        firstVowelIndex = word.length;
    }

    // Translate the word based on the position of the first vowel
    if (firstVowelIndex === 0) {
        return word + 'way';
    } else {
        return word.slice(firstVowelIndex) + word.slice(0, firstVowelIndex) + 'ay';
    }
}

