function rle_compress(s: string): string {
    if (s.length === 0) return s;

    let compressed = '';
    let count = 1;

    for (let i = 1; i <= s.length; i++) {
        if (s[i] === s[i - 1]) {
            count++;
        } else {
            compressed += s[i - 1] + (count > 1 ? count.toString() : '');
            count = 1;
        }
    }

    return compressed.length < s.length ? compressed : s;
}

