function poker_hand(cards: string[]): string {
    const ranks = "23456789TJQKA";
    const suits = "CDHS";
    const rankValues = new Map([...ranks].map((r, i) => [r, i]));
    const suitCounts = new Map(suits.split('').map(s => [s, 0]));
    const rankCounts = new Map([...ranks].map(r => [r, 0]));

    // Validate and count cards
    for (const card of cards) {
        if (card.length !== 2 || !ranks.includes(card[0]) || !suits.includes(card[1])) return "invalid";
        suitCounts.set(card[1], suitCounts.get(card[1])! + 1);
        rankCounts.set(card[0], rankCounts.get(card[0])! + 1);
    }

    // Check for unique cards
    if ([...suitCounts.values()].some(count => count > 1) || [...rankCounts.values()].some(count => count > 1)) return "invalid";

    // Check for straight flush
    if (suitCounts.size === 1 && [...rankCounts.values()].every(count => count === 1)) {
        const sortedRanks = [...rankCounts.keys()].map(r => rankValues.get(r)!);
        if (sortedRanks.every((r, i, arr) => i === 0 || r === arr[i - 1] + 1) || (sortedRanks[0] === 0 && sortedRanks[1] === 12 && sortedRanks.slice(2).every((r, i, arr) => r === arr[i - 1] + 1))) return "straight flush";
    }

    // Check for four of a kind
    if ([...rankCounts.values()].some(count => count === 4)) return "four of a kind";

    // Check for full house
    if ([...rankCounts.values()].includes(3) && [...rankCounts.values()].includes(2)) return "full house";

    // Check for flush
    if (suitCounts.size === 1) return "flush";

    // Check for straight
    const sortedRanks = [...rankCounts.keys()].map(r => rankValues.get(r)!);
    if (sortedRanks.every((r, i, arr) => i === 0 || r === arr[i - 1] + 1) || (sortedRanks[0] === 0 && sortedRanks[1] === 12 && sortedRanks.slice(2).every((r, i, arr) => r === arr[i - 1] + 1))) return "straight";

    // Check for three of a kind
    if ([...rankCounts.values()].some(count => count === 3)) return "three of a kind";

    // Check for two pair
    if ([...rankCounts.values()].filter(count => count === 2).length === 2) return "two pair";

    // Check for one pair
    if ([...rankCounts.values()].some(count => count === 2)) return "one pair";

    // High card
    return "high card";
}

