function rle_decode(s: string): Result<string> {
    let result = '';
    let i = 0;

    while (i < s.length) {
        const char = s[i++];
        if (char >= '0' && char <= '9') {
            return { ok: false, error: 'missing character before count' };
        }

        let count = 1;
        if (i < s.length && s[i] >= '0' && s[i] <= '9') {
            count = parseInt(s[i++]);
            if (count === 0) {
                return { ok: false, error: `bad count for ${char}` };
            }
        }

        result += char.repeat(count);
    }

    return { ok: true, value: result };
}

