type Cmd = { kind: "Forward"; steps: number } | { kind: "TurnLeft" } | { kind: "TurnRight" };

export function robot_walk(cmds: Cmd[], obstacles: ([number, number])[]): [number, number, string] {
    let x = 0, y = 0, direction = "N";

    const move = (dx: number, dy: number) => {
        if (!obstacles.some(([ox, oy]) => ox === x + dx && oy === y + dy)) {
            x += dx;
            y += dy;
        }
    };

    for (const cmd of cmds) {
        switch (cmd.kind) {
            case "Forward":
                switch (direction) {
                    case "N": move(0, cmd.steps); break;
                    case "E": move(cmd.steps, 0); break;
                    case "S": move(0, -cmd.steps); break;
                    case "W": move(-cmd.steps, 0); break;
                }
                break;
            case "TurnLeft":
                direction = direction === "N" ? "W" : direction === "W" ? "S" : direction === "S" ? "E" : "N";
                break;
            case "TurnRight":
                direction = direction === "N" ? "E" : direction === "E" ? "S" : direction === "S" ? "W" : "N";
                break;
        }
    }

    return [x, y, direction];
}

