type Expense = { payer: string; amount_cents: number };

function settle_debts(expenses: Expense[], people: string[]): ([string, string, number])[] {
    const total = expenses.reduce((acc, exp) => acc + exp.amount_cents, 0);
    const perPerson = Math.floor(total / people.length);
    const remainder = total % people.length;
    const balances = people.reduce((acc, person, index) => {
        acc[person] = perPerson + (index < remainder ? 1 : 0);
        return acc;
    }, {} as Record<string, number>);

    const payments: [string, string, number][] = [];
    while (true) {
        const debtor = people.find(p => balances[p] < 0);
        const creditor = people.find(p => balances[p] > 0);
        if (!debtor || !creditor) break;
        const amount = Math.min(-balances[debtor], balances[creditor]);
        balances[debtor] += amount;
        balances[creditor] -= amount;
        payments.push([debtor, creditor, amount]);
    }

    return payments;
}

