function parse_duration(s: string): Result<number> {
    if (s === "") return { ok: false, error: "empty" };

    let seconds = 0;
    let lastUnit: 'h' | 'm' | 's' | null = null;

    for (let i = 0; i < s.length; ) {
        let num = 0;
        while (i < s.length && s[i] >= '0' && s[i] <= '9') {
            num = num * 10 + (s[i] - '0');
            i++;
        }

        if (i === s.length) return { ok: false, error: "missing unit" };

        const unit = s[i];
        i++;

        if (unit !== 'h' && unit !== 'm' && unit !== 's') {
            return { ok: false, error: `unknown unit: ${unit}` };
        }

        if (lastUnit !== null && unitsOrder[unit] <= unitsOrder[lastUnit]) {
            return { ok: false, error: `unit out of order: ${unit}` };
        }

        seconds += num * durations[unit];
        lastUnit = unit;
    }

    return { ok: true, value: seconds };
}

