function tic_tac_toe(board: string[]): string {
    const rows = board;
    const cols = board.map(row => row[0] + row[1] + row[2]);
    const diags = [board[0][0] + board[1][1] + board[2][2], board[0][2] + board[1][1] + board[2][0]];
    const allLines = [...rows, ...cols, ...diags];
    const xCount = board.join('').split('').filter(c => c === 'X').length;
    const oCount = board.join('').split('').filter(c => c === 'O').length;

    if (Math.abs(xCount - oCount) !== 1 && xCount !== oCount) return "invalid";

    const hasLine = (player: string) => allLines.some(line => line === player.repeat(3));
    if (hasLine('X') && xCount !== oCount + 1) return "invalid";
    if (hasLine('O') && xCount !== oCount) return "invalid";

    if (hasLine('X')) return "X wins";
    if (hasLine('O')) return "O wins";
    if (board.every(row => row.split('').every(cell => cell !== '.'))) return "draw";
    return "in progress";
}

