type Student = { name: string; scores: number[] };

function student_medians(students: Student[]): ([string, number])[] {
    return students
        .filter(student => student.scores.length > 0)
        .map(student => ({
            name: student.name,
            median: calculateMedian(student.scores)
        }))
        .sort((a, b) => {
            if (a.median === b.median) {
                return a.name.localeCompare(b.name);
            }
            return b.median - a.median;
        });
}

function calculateMedian(scores: number[]): number {
    const sortedScores = scores.slice().sort((a, b) => a - b);
    const midIndex = Math.floor(sortedScores.length / 2);
    if (sortedScores.length % 2 === 0) {
        return (sortedScores[midIndex - 1] + sortedScores[midIndex]) / 2;
    } else {
        return sortedScores[midIndex];
    }
}

