type EditOp =
  | { kind: "Insert"; text: string }
  | { kind: "Delete"; n: number }
  | { kind: "Left"; n: number }
  | { kind: "Right"; n: number }
  | { kind: "Undo" };

function text_editor(ops: EditOp[]): string {
  let text = "";
  let cursor = 0;
  let history: { text: string; cursor: number }[] = [];

  for (const op of ops) {
    history.push({ text, cursor });
    switch (op.kind) {
      case "Insert":
        text = text.slice(0, cursor) + op.text + text.slice(cursor);
        cursor += op.text.length;
        break;
      case "Delete":
        const deleteCount = Math.min(op.n, cursor);
        text = text.slice(0, cursor - deleteCount) + text.slice(cursor);
        cursor -= deleteCount;
        break;
      case "Left":
        cursor = Math.max(0, cursor - op.n);
        break;
      case "Right":
        cursor = Math.min(text.length, cursor + op.n);
        break;
      case "Undo":
        if (history.length > 1) {
          history.pop();
          const { text, cursor } = history[history.length - 1];
          this.text = text;
          this.cursor = cursor;
        }
        break;
    }
  }

  return text;
}

