function tokenize(s: string): Result<Token[]> {
  const tokens: Token[] = [];
  let i = 0;

  while (i < s.length) {
    if (s[i] === ' ') {
      i++;
      continue;
    }

    if (s[i] >= '0' && s[i] <= '9') {
      let num = 0;
      while (i < s.length && s[i] >= '0' && s[i] <= '9') {
        num = num * 10 + (s[i] - '0');
        i++;
      }
      tokens.push({ kind: "Num", value: num });
      continue;
    }

    if (s[i] >= 'a' && s[i] <= 'z' || s[i] === '_') {
      let name = s[i];
      i++;
      while (i < s.length && (s[i] >= 'a' && s[i] <= 'z' || s[i] >= '0' && s[i] <= '9' || s[i] === '_')) {
        name += s[i];
        i++;
      }
      tokens.push({ kind: "Ident", name });
      continue;
    }

    const twoCharSymbols: { [key: string]: Token } = {
      "==": { kind: "Sym", text: "==" },
      "<=": { kind: "Sym", text: "<=" },
      ">=": { kind: "Sym", text: ">=" },
      "!=": { kind: "Sym", text: "!=" }
    };

    if (i + 1 < s.length && twoCharSymbols[s.slice(i, i + 2)]) {
      tokens.push(twoCharSymbols[s.slice(i, i + 2)]);
      i += 2;
      continue;
    }

    const oneCharSymbols: { [key: string]: Token } = {
      "+": { kind: "Sym", text: "+" },
      "-": { kind: "Sym", text: "-" },
      "*": { kind: "Sym", text: "*" },
      "/": { kind: "Sym", text: "/" },
      "=": { kind: "Sym", text: "=" },
      "<": { kind: "Sym", text: "<" },
      ">": { kind: "Sym", text: ">" },
      "(": { kind: "Sym", text: "(" },
      ")": { kind: "Sym", text: ")" },
      ",": { kind: "Sym", text: "," }
    };

    if (oneCharSymbols[s[i]]) {
      tokens.push(oneCharSymbols[s[i]]);
      i++;
      continue;
    }

    return { ok: false, error: `unexpected character: ${s[i]} at ${i}` };
  }

  return { ok: true, value: tokens };
}

