export function top_product_per_region(sales: Sale[]): ([string, string, number])[] {
    const revenueMap = new Map<string, { product: string; revenue: number }>();

    for (const sale of sales) {
        const key = `${sale.region}-${sale.product}`;
        const current = revenueMap.get(key) || { product: sale.product, revenue: 0 };
        current.revenue += sale.units * sale.price_cents;
        revenueMap.set(key, current);
